#include<bits/stdc++.h>
using namespace std;
#define int long long

signed main() {
    ios::sync_with_stdio(0);
    cin.tie(0),cout.tie(0);
    auto solve = [&]() {
        int n, m;
        cin >> n >> m;

        vector<int> a(n);
        for (int &x : a) cin >> x;

        priority_queue<int> pq;
        int sum = 0, ans = LLONG_MIN;

        for (int i = 0; i < n; ++i) {
            if ((int)pq.size() == m - 1) {
                ans = max(ans, m * a[i] - sum);
            }

            pq.push(a[i]);
            sum += a[i];
            if ((int)pq.size() == m) {
                sum -= pq.top();
                pq.pop();
            }
        }

        cout << ans << '\n';
    };
    int t;
    for(cin>>t;t;t--)
    solve();
    return 0;
}

